async function piAirbnbPageLooksLoggedIn(page) {
  const url = page.url();
  // Login footer contains the word "Hosting" — never treat body text as logged-in.
  if (!/airbnb\.com\/hosting(\/|$|\?)/i.test(url)) return false;
  if (/log.?in|sign.?in|authenticate/i.test(url)) return false;
  if (await page.locator('input[type="password"], #otp-code-input, #phone-or-email').count()) return false;
  const text = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ');
  if (/enter your password|log in to continue|try another way|verify that you.?re human/i.test(text)) return false;
  return true;
}

